  .map(line => line.replace(/:/g, '='))
studio.writeLines('docs/normalized.txt', output)

local S = {
  xs = 4, sm = 8, md = 16, lg = 24, xl = 40,   -- spacing
  margin = 16,                                 -- page margin
  radius = 8, radius_lg = 16,                  -- corner radius
  line = 2, line_bold = 3,                     -- line width
  hit = 44, bar = 16,                          -- smallest tap target, thin bar height
  tile = 96, tile_min = 132,                   -- tiles
  dialog_w = 400,                              -- widest dialog
}

function on_load(ctx)
  F = { big = ctx.fonts:size(40), title = ctx.fonts:size(30), body = ctx.fonts:size(24), small = ctx.fonts:size(20) }
  S.control = math.max(S.hit, F.body.line_height + 2 * S.sm)   -- height of one-line controls
end

local S = {
  xs = 4, sm = 8, md = 16, lg = 24, xl = 40,   -- 间距
  margin = 16,                                 -- 页边距
  radius = 8, radius_lg = 16,                  -- 圆角
  line = 2, line_bold = 3,                     -- 线宽
  hit = 44, bar = 16,                          -- 最小热区、细条的高
  tile = 96, tile_min = 132,                   -- 宫格
  dialog_w = 400,                              -- 弹窗最大宽
}

function on_load(ctx)
  F = { big = ctx.fonts:size(40), title = ctx.fonts:size(30), body = ctx.fonts:size(24), small = ctx.fonts:size(20) }
  S.control = math.max(S.hit, F.body.line_height + 2 * S.sm)   -- 单行控件的高
end

local b = ctx.device:battery()   -- { percent, charging }
local r = ctx.device:radios()    -- { wifi_on, wifi_connected, bluetooth_on }
local d = ctx.device:display()   -- { dark } (2.12)
ctx.device:keep_awake(ms)        -- postpone idle auto power-off (2.18)
local s = ctx.device:shake()     -- shake to turn pages: 0 / -1 / 1 (2.33.2, optional capability shake)

ctx.dialog:confirm({ title = "Delete the record", message = "This cannot be undone.", ok_text = "Delete" },
  function(ctx, ok) if ok then remove_record() end end)

ctx.dialog:choose({ title = "Sort", items = { "By time", "By name" }, selected = 1 },
  function(ctx, index) if index then sort_by = index; ctx:invalidate() end end)

ctx.dialog:toast("Saved")

local f = ctx.frontlight:get()                       -- { on, brightness, warmth }
ctx.frontlight:set({ on = true, brightness = 20 })   -- write only the fields to change
ctx.frontlight:reset()                               -- back to the user's settings

local scan, err = ctx.ble:scan({
  duration_ms = 5000,     -- 100–30000, default 5000
  name = "Mi",            -- optional: only devices whose name contains it
  services = { "180d" },  -- optional: only devices advertising any of these services
  active = true,          -- default true: request scan responses (to get the full name)
  limit = 20,             -- 1–40, default 20
}, {
  on_device = function(ctx, scan, dev) end,          -- optional: the first time each address matches
  on_done = function(ctx, scan, devices, err) end,   -- required: sorted from strongest to weakest signal
})
scan:stop()   -- end early; on_done is still called once; calling again after it ends does nothing

